def is_balanced(s: str) -> bool:
    """
    Checks if parentheses in a string are balanced.

    Args:
        s: The input string containing parentheses.

    Returns:
        True if parentheses are balanced, False otherwise.
    """
    balance = 0
    for char in s:
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1

        if balance < 0:
            return False

    return balance == 0

def main() -> None:
    """
    Tests the is_balanced function with predefined strings and prints results.
    """
    test_strings = [
        "(())",
        "(()",
        "())()",
        "()(())",
    ]

    for s in test_strings:
        if is_balanced(s):
            print("true")
        else:
            print("false")

if __name__ == "__main__":
    main()

