module benchmark/solution

type Tree =
  | Leaf(int)
  | Node(Tree, int, Tree)

export func treeSum(t: Tree) -> int {
  match t {
    Leaf(v) => v,
    Node(l, v, r) => treeSum(l) + v + treeSum(r)
  }
}

export func main() -> () ! {IO} {
  let tree =
    Node(
      Node(Leaf(1), 3, Leaf(4)),
      5,
      Node(Leaf(0), 8, Leaf(10))
    );
  -- Correct the right child to match structure: no left child, only right 10
  let fixedTree =
    match tree {
      Node(left, v, Node(_, rv, rr)) =>
        Node(left, v, Node(Leaf(0), rv, rr)),
      _ => tree
    };
  -- But we actually want exactly: Node(Node(Leaf(1),3,Leaf(4)),5,Node(Leaf(0),8,Leaf(10)))
  -- Sum of actual values: 1 + 3 + 4 + 5 + 8 + 10 = 31
  let actualTree = Node(
    Node(Leaf(1), 3, Leaf(4)),
    5,
    Node(Leaf(8), 10, Leaf(0))
  );
  -- Instead, construct the correct tree directly:
  let correctTree =
    Node(
      Node(Leaf(1), 3, Leaf(4)),
      5,
      Node(Leaf(8), 10, Leaf(0))
    );
  -- Final proper tree as specified:
  let finalTree =
    Node(
      Node(Leaf(1), 3, Leaf(4)),
      5,
      Node(Leaf(0), 8, Leaf(10))
    );
  let sum = treeSum(finalTree);
  print(show(sum))
}

