import std/io (println)
import std/fs (writeFile, readFile)
import std/json (encode, decode, jo, ja, kv, js, jnum, Json, JObject, JString, JNumber, JArray)
import std/result (Result, Ok, Err)
import std/list (length)
import std/string (split)

-- Helper to find a key in the JSON object list
func findKey(kvs: [{key: string, value: Json}], target: string) -> Result[Json, string] {
  match kvs {
    [] => Err("Key not found: " ++ target),
    pair :: rest =>
      if pair.key == target
      then Ok(pair.value)
      else findKey(rest, target)
  }
}

export func main() -> () ! {IO, FS} {
  -- 1. Create config object
  let config = jo([
    kv("app_name", js("MyApp")),
    kv("version", js("1.0.0")),
    kv("port", jnum(8080.0)),
    kv("features", ja([js("logging"), js("auth"), js("api")]))
  ]);

  -- 2. Write JSON file
  writeFile("app_config.json", encode(config));

  -- 3. Read and validate
  let content = readFile("app_config.json");

  match decode(content) {
    Ok(JObject(fields)) => {
      match findKey(fields, "app_name") {
        Ok(JString(appName)) => {
          match findKey(fields, "version") {
            Ok(JString(ver)) => {
              if length(split(ver, ".")) == 3 then {
                match findKey(fields, "port") {
                  Ok(JNumber(portVal)) => {
                    if portVal >= 1024.0 && portVal <= 65535.0 then {
                      match findKey(fields, "features") {
                        Ok(JArray(feats)) => {
                          if length(feats) > 0 then {
                            let portInt = floatToInt(portVal);
                            let count = length(feats);
                            println("Loaded " ++ appName ++ " v" ++ ver ++ " on port " ++ show(portInt) ++ " with " ++ show(count) ++ " features")
                          } else {
                            println("Error: Features list is empty")
                          }
                        },
                        _ => println("Error: Invalid features type")
                      }
                    } else {
                      println("Error: Port out of range")
                    }
                  },
                  _ => println("Error: Invalid port type")
                }
              } else {
                println("Error: Version format invalid (expected X.Y.Z)")
              }
            },
            _ => println("Error: Invalid version type")
          }
        },
        _ => println("Error: Invalid app_name type")
      }
    },
    Ok(_) => println("Error: Root must be an object"),
    Err(msg) => println("Error parsing JSON: " ++ msg)
  }
}

