from typing import TypeVar, Generic, Union

T = TypeVar('T')

class Result(Generic[T]):
    """
    A type representing either a successful value (Ok) or an error (Err).
    Similar to Rust's Result enum.
    """
    _is_ok: bool
    _value: Union[T, str]

    def __init__(self, is_ok: bool, value: Union[T, str]) -> None:
        self._is_ok = is_ok
        self._value = value

    @classmethod
    def ok(cls, value: T) -> 'Result[T]':
        """Constructs an Ok variant containing the success value."""
        return cls(True, value)

    @classmethod
    def err(cls, message: str) -> 'Result[T]':
        """Constructs an Err variant containing the error message."""
        return cls(False, message)

    def is_ok(self) -> bool:
        """Returns True if the result is Ok."""
        return self._is_ok

    def is_err(self) -> bool:
        """Returns True if the result is Err."""
        return not self._is_ok

    def unwrap(self) -> T:
        """
        Returns the contained Ok value.
        Raises ValueError if the value is an Err.
        """
        if self._is_ok:
            return self._value  # type: ignore
        raise ValueError(f"Called `unwrap` on an `Err` value: {self._value}")

    def unwrap_err(self) -> str:
        """
        Returns the contained Err value.
        Raises ValueError if the value is an Ok.
        """
        if not self._is_ok:
            return self._value  # type: ignore
        raise ValueError(f"Called `unwrap_err` on an `Ok` value: {self._value}")

    def __repr__(self) -> str:
        if self._is_ok:
            return f"Ok({repr(self._value)})"
        return f"Err({repr(self._value)})"


def parse_int(s: str) -> Result[int]:
    """
    Attempts to parse a string into an integer.
    Returns Ok(n) if successful, Err("Invalid integer") otherwise.
    """
    try:
        n = int(s)
        return Result.ok(n)
    except ValueError:
        return Result.err("Invalid integer")


def divide_safe(a: int, b: int) -> Result[int]:
    """
    Performs integer division safely.
    Returns Ok(a/b) if b is not zero, Err("Division by zero") otherwise.
    """
    if b == 0:
        return Result.err("Division by zero")
    return Result.ok(a // b)


def main() -> None:
    # Test case 1: parse_int("10") then divide by 2 -> "Result: 5"
    parsed_a_res = parse_int("10")
    final_op_res: Result[int]

    if parsed_a_res.is_ok():
        final_op_res = divide_safe(parsed_a_res.unwrap(), 2)
    else:
        final_op_res = Result.err(parsed_a_res.unwrap_err()) # Propagate parse error

    if final_op_res.is_ok():
        print(f"Result: {final_op_res.unwrap()}")
    else:
        print(f"Error: {final_op_res.unwrap_err()}")

    # Test case 2: parse_int("10") then divide by 0 -> "Error: Division by zero"
    parsed_a_res = parse_int("10")
    # Initialize with a default Err for type checker, it will be reassigned
    final_op_res = Result.err("placeholder") 

    if parsed_a_res.is_ok():
        final_op_res = divide_safe(parsed_a_res.unwrap(), 0)
    else:
        final_op_res = Result.err(parsed_a_res.unwrap_err())

    if final_op_res.is_ok():
        print(f"Result: {final_op_res.unwrap()}")
    else:
        print(f"Error: {final_op_res.unwrap_err()}")

    # Test case 3: parse_int("abc") -> "Error: Invalid integer"
    parsed_a_res = parse_int("abc")
    # Initialize with a default Err for type checker, it will be reassigned
    final_op_res = Result.err("placeholder") 

    if parsed_a_res.is_ok():
        # This branch won't be executed, as parsing "abc" will result in an error.
        # If it were Ok, we would proceed with division.
        final_op_res = divide_safe(parsed_a_res.unwrap(), 2) 
    else:
        final_op_res = Result.err(parsed_a_res.unwrap_err())

    if final_op_res.is_ok():
        print(f"Result: {final_op_res.unwrap()}")
    else:
        print(f"Error: {final_op_res.unwrap_err()}")


if __name__ == "__main__":
    main()

