import dataclasses
from typing import Union

@dataclasses.dataclass(frozen=True)
class Num:
    value: int

@dataclasses.dataclass(frozen=True)
class Add:
    left: 'Expr'
    right: 'Expr'

@dataclasses.dataclass(frozen=True)
class Mul:
    left: 'Expr'
    right: 'Expr'

Expr = Union[Num, Add, Mul]

def evaluate(expression: Expr) -> int:
    """
    Evaluates an expression AST to an integer.
    """
    if isinstance(expression, Num):
        return expression.value
    elif isinstance(expression, Add):
        return evaluate(expression.left) + evaluate(expression.right)
    elif isinstance(expression, Mul):
        return evaluate(expression.left) * evaluate(expression.right)
    else:
        raise TypeError(f"Unknown expression type: {type(expression)}")

def main() -> None:
    """
    Constructs and evaluates the specified expression, then prints the result.
    """
    # (3 + 4) * (2 + 5)
    expression_ast = Mul(
        Add(Num(3), Num(4)),
        Add(Num(2), Num(5))
    )

    result = evaluate(expression_ast)
    print(result)

if __name__ == "__main__":
    main()

