    [] => [x],
    y :: rest => y :: enqueue(x, rest)
  }
}

-- Enqueue all elements from a list
export func enqueueAll(toAdd: [int], queue: [int]) -> [int] {
  match toAdd {
    [] => queue,
    x :: rest => enqueueAll(rest, enqueue(x, queue))
  }
}

-- Get neighbors of a node from adjacency list
export func getNeighbors(node: int, graph: [(int, [int])]) -> [int] {
  match graph {
    [] => [],
    entry :: rest => match entry {
      (n, neighbors) => if n == node then neighbors else getNeighbors(node, rest)
    }
  }
}

-- Filter out already visited nodes
export func filterUnvisited(nodes: [int], visited: [int]) -> [int] {
  match nodes {
    [] => [],
    x :: rest => if contains(x, visited)
                 then filterUnvisited(rest, visited)
                 else x :: filterUnvisited(rest, visited)
  }
}

-- BFS helper: takes queue, visited list, graph, returns visit order
export func bfsHelper(queue: [int], visited: [int], graph: [(int, [int])]) -> [int] {
  match queue {
    [] => [],
    current :: restQueue => 
      if contains(current, visited)
      then bfsHelper(restQueue, visited, graph)
      else {
        let newVisited = current :: visited;
        let neighbors = getNeighbors(current, graph);
        let unvisitedNeighbors = filterUnvisited(neighbors, newVisited);
        let newQueue = enqueueAll(unvisitedNeighbors, restQueue);
        current :: bfsHelper(newQueue, newVisited, graph)
      }
  }
}

