type Term =
  | TVar(string)
  | TLam(string, Term)
  | TApp(Term, Term)

export func subst(term: Term, v: string, repl: Term) -> Term {
  match term {
    TVar(name) =>
      if name == v
      then repl
      else TVar(name),
    TLam(param, body) =>
      if param == v
      then TLam(param, body)
      else TLam(param, subst(body, v, repl)),
    TApp(f, a) =>
      TApp(subst(f, v, repl), subst(a, v, repl))
  }
}

export func isValue(t: Term) -> bool {
  match t {
    TLam(_, _) => true,
    TVar(_) => true,
    TApp(_, _) => false
  }
}

export func eval(term: Term) -> Term {
  match term {
    TVar(_) => term,
    TLam(_, _) => term,
    TApp(f, a) => {
      let vf = eval(f);
      let va = eval(a);
      match vf {
        TLam(param, body) =>
          eval(subst(body, param, va)),
        _ =>
          TApp(vf, va)
      }
    }
  }
}

export func showTerm(t: Term) -> string {
  match t {
    TVar(name) => name,
    TLam(param, body) => "(\\" ++ param ++ ". " ++ showTerm(body) ++ ")",
    TApp(f, a) => "(" ++ showTerm(f) ++ " " ++ showTerm(a) ++ ")"
  }
}

