from dataclasses import dataclass
from typing import Union

@dataclass(frozen=True)
class TVar:
    name: str

@dataclass(frozen=True)
class TLam:
    param: str
    body: 'Term'

@dataclass(frozen=True)
class TApp:
    func: 'Term'
    arg: 'Term'

Term = Union[TVar, TLam, TApp]

def subst(term: Term, var: str, replacement: Term) -> Term:
    if isinstance(term, TVar):
        if term.name == var:
            return replacement
        else:
            return term
    elif isinstance(term, TLam):
        if term.param == var:
            return term
        else:
            return TLam(term.param, subst(term.body, var, replacement))
    elif isinstance(term, TApp):
        return TApp(subst(term.func, var, replacement), subst(term.arg, var, replacement))
    else:
        raise TypeError(f"Unknown term type: {type(term)}")

def evaluate(term: Term) -> Term:
    if isinstance(term, TVar) or isinstance(term, TLam):
        return term
    elif isinstance(term, TApp):
        f_prime = evaluate(term.func)
        arg_prime = evaluate(term.arg)

        if isinstance(f_prime, TLam):
            return evaluate(subst(f_prime.body, f_prime.param, arg_prime))
        else:
            return TApp(f_prime, arg_prime)
    else:
        raise TypeError(f"Unknown term type: {type(term)}")

def main():
    # (λx. λy. x) 1 2
    # AST: TApp(TApp(TLam("x", TLam("y", TVar("x"))), TVar("1")), TVar("2"))

    k_combinator = TLam("x", TLam("y", TVar("x")))

    # Apply K to 1: (λx. λy. x) 1
    k_applied_to_1 = TApp(k_combinator, TVar("1"))

    # Apply the result to 2: ((λx. λy. x) 1) 2
    final_expression = TApp(k_applied_to_1, TVar("2"))

    result = evaluate(final_expression)
    print(result)

if __name__ == "__main__":
    main()

