module benchmark/solution

import std/fs (readFile, writeFile)
import std/string (split, substring, find, trim, compare)
import std/option (Option, Some, None)
import std/list (length, head, tail)

-- Tuple accessors (assuming they are not built-in for tuples)
func fst[a, b](pair: (a, b)) -> a = match pair { (x, _) => x }
func snd[a, b](pair: (a, b)) -> b = match pair { (_, y) => y }

-- Type alias for log counts
type LogCounts = { info: int, error: int, warning: int }

-- Helper function to check if an element exists in a list
func contains[a](xs: [a], x: a) -> bool {
  match xs {
    [] => false,
    y :: rest => if y == x then true else contains(rest, x)
  }
}

-- Helper function to get an element at a specific index from a list of strings
-- Returns Option[string] to handle out-of-bounds access safely
func getPart(parts: [string], index: int) -> Option[string] {
  if index < 0 then None
  else match parts {
    [] => None,
    x :: rest => if index == 0 then Some(x) else getPart(rest, index - 1)
  }
}

-- Helper function to get a sublist starting from a specific index
func getSubList(parts: [string], index: int) -> [string] {
  if index <= 0 then parts
  else match parts {
    [] => [],
    _ :: rest => getSubList(rest, index - 1)
  }
}

-- Helper function to insert a string into a sorted list (for insertion sort)
func insertSorted(elem: string, xs: [string]) -> [string] {
  match xs {
    [] => [elem],
    x :: rest =>
      if compare(elem, x) <= 0 -- elem is less than or equal to x
      then elem :: xs
      else x :: insertSorted(elem, rest)
  }
}

-- Recursive insertion sort for a list of strings
func sortStrings(xs: [string]) -> [string] {
  match xs {
    [] => [],
    x :: rest => insertSorted(x, sortStrings(rest))
  }
}

-- Removes duplicate consecutive elements from a sorted list
func uniqueSorted(xs: [string]) -> [string] {
  match xs {
    [] => [],
    [x] => [x],
    x :: y :: rest => if x == y then uniqueSorted(y :: rest) else x :: uniqueSorted(y :: rest)
  }
}

-- Joins a list of strings with a separator
func join(sep: string, xs: [string]) -> string {
  match xs {
    [] => "",
    [x] => x,
    x :: rest => x ++ sep ++ join(sep, rest)
  }
}

-- Extracts a username from a message string if it matches a login/logout pattern
func extractUsername(message: string) -> Option[string] {
  let loginPattern = "User logged in: " in
  let logoutPattern = "User logged out: " in
  let loginIdx = find(message, loginPattern) in
  let logoutIdx = find(message, logoutPattern) in

  if loginIdx != -1 then
    let startIdx = loginIdx + length(loginPattern) in
    Some(substring(message, startIdx, length(message)))
  else if logoutIdx != -1 then
    let startIdx = logoutIdx + length(logoutPattern) in
    Some(substring(message, startIdx, length(message)))
  else None
}

-- Parses a single log line to extract its level and a potential username
func parseLine(line: string) -> {level: string, username: Option[string]} {
  let parts = split(line, " ") in

  -- Extract level (3rd part of the line)
  let levelOpt = getPart(parts, 2) in
  let level = match levelOpt { Some(l) => l, None => "" } in

  -- Reconstruct the message part (from 4th part onwards)
  let messageParts = getSubList(parts, 3) in
  let message = join(" ", messageParts) in

  -- Extract username from the message
  let username = extractUsername(message) in

  { level: level, username: username }
}

-- Recursively analyzes a list of log lines, accumulating counts and users
func analyzeLogs(lines: [string], accCounts: LogCounts, accUsers: [string]) -> (LogCounts, [string]) {
  match lines {
    [] => (accCounts, accUsers),
    line :: rest => {
      let parsed = parseLine(line) in

      -- Update log level counts
      let newCounts =
        if parsed.level == "INFO" then { accCounts | info: accCounts.info + 1 }
        else if parsed.level == "ERROR" then { accCounts | error: accCounts.error + 1 }
        else if parsed.level == "WARNING" then { accCounts | warning: accCounts.warning + 1 }
        else accCounts in

      -- Add username to the list (duplicates allowed at this stage)
      let newUsers =
        match parsed.username {
          Some(u) => u :: accUsers,
          None => accUsers
        } in

      analyzeLogs(rest, newCounts, newUsers)
    }
  }
}

export func main() -> () ! {IO, FS} {
  let logFileName = "app.log" in
  let logContent =
    "2024-10-29 10:00:00 INFO User logged in: alice\n" ++
    "2024-10-29 10:01:15 ERROR Database connection failed\n" ++
    "2024-10-29 10:02:30 INFO User logged in: bob\n" ++
    "2024-10-29 10:03:45 WARNING High memory usage: 85%\n" ++
    "2024-10-29 10:05:00 ERROR API timeout: /users endpoint\n" ++
    "2024-10-29 10:06:15 INFO User logged out: alice" in

  -- 1. Create log file
  writeFile(logFileName, logContent);

  -- 2. Read log file
  let readContent = readFile(logFileName) in
  let lines = split(readContent, "\n") in
  let totalEntries = length(lines) in

  -- 3. Parse and analyze the log
  let initialCounts = { info: 0, error: 0, warning: 0 } in
  let initialUsers = [] in
  let analysisResult = analyzeLogs(lines, initialCounts, initialUsers) in
  let finalCounts = fst(analysisResult) in
  let allUsers = snd(analysisResult) in

  -- Process users: sort and make unique
  let sortedUsers = sortStrings(allUsers) in
  let finalUniqueSortedUsers = uniqueSorted(sortedUsers) in
  let usersString = join(", ", finalUniqueSortedUsers) in

  -- 4. Calculate percentages (using integer division, which rounds down for positive numbers)
  let infoPct = if totalEntries == 0 then 0 else finalCounts.info * 100 / totalEntries in
  let errorPct = if totalEntries == 0 then 0 else finalCounts.error * 100 / totalEntries in
  let warningPct = if totalEntries == 0 then 0 else finalCounts.warning * 100 / totalEntries in

  -- 5. Print results in the exact specified format
  print("Total log entries: " ++ show(totalEntries));
  print("INFO: " ++ show(finalCounts.info) ++ " (" ++ show(infoPct) ++ "%)");
