def merge(xs: list[int], ys: list[int]) -> list[int]:
    """Merges two sorted lists into one sorted list."""
    result: list[int] = []
    i, j = 0, 0
    while i < len(xs) and j < len(ys):
        if xs[i] < ys[j]:
            result.append(xs[i])
            i += 1
        else:
            result.append(ys[j])
            j += 1
    result.extend(xs[i:])
    result.extend(ys[j:])
    return result


def split(xs: list[int]) -> tuple[list[int], list[int]]:
    """Splits a list into two halves."""
    mid = len(xs) // 2
    return xs[:mid], xs[mid:]


def merge_sort(xs: list[int]) -> list[int]:
    """Recursively sorts a list using the merge sort algorithm."""
    if len(xs) <= 1:
        return xs
    left, right = split(xs)
    sorted_left = merge_sort(left)
    sorted_right = merge_sort(right)
    return merge(sorted_left, sorted_right)


def main() -> None:
    """Sorts a predefined list using merge sort and prints the result."""
    data = [38, 27, 43, 3, 9, 82, 10]
    sorted_data = merge_sort(data)
    print(sorted_data)


if __name__ == "__main__":
    main()

