from dataclasses import dataclass
from typing import List, Tuple, Union

@dataclass
class Num:
    value: int

@dataclass
class Var:
    name: str

@dataclass
class Add:
    left: 'Expr'
    right: 'Expr'

@dataclass
class Mul:
    left: 'Expr'
    right: 'Expr'

@dataclass
class Let:
    name: str
    value: 'Expr'
    body: 'Expr'

Expr = Union[Num, Var, Add, Mul, Let]
Env = List[Tuple[str, int]]

def lookup(name: str, env: Env) -> int:
    for var_name, value in reversed(env):
        if var_name == name:
            return value
    raise NameError(f"Variable '{name}' not found")

def eval(expr: Expr, env: Env) -> int:
    if isinstance(expr, Num):
        return expr.value
    elif isinstance(expr, Var):
        return lookup(expr.name, env)
    elif isinstance(expr, Add):
        return eval(expr.left, env) + eval(expr.right, env)
    elif isinstance(expr, Mul):
        return eval(expr.left, env) * eval(expr.right, env)
    elif isinstance(expr, Let):
        value = eval(expr.value, env)
        new_env = env + [(expr.name, value)]
        return eval(expr.body, new_env)
    else:
        raise TypeError(f"Unknown expression type: {type(expr)}")

def main():
    program = Let("x", Num(5), Let("y", Add(Var("x"), Num(3)), Mul(Var("x"), Var("y"))))
    result = eval(program, [])
    print(result)

if __name__ == "__main__":
    main()

