from enum import Enum, auto
from typing import Optional, List

class Color(Enum):
    RED = auto()
    BLACK = auto()

class Node:
    def __init__(self, color: Color, left: Optional['Node'], val: int, right: Optional['Node']):
        self.color = color
        self.left = left
        self.val = val
        self.right = right

def balance(color: Color, left: Optional[Node], val: int, right: Optional[Node]) -> Node:
    if color == Color.BLACK:
        # Case 1: Left child is Red, Left's Left child is Red
        if left and left.color == Color.RED and left.left and left.left.color == Color.RED:
            return Node(Color.RED,
                        Node(Color.BLACK, left.left.left, left.left.val, left.left.right),
                        left.val,
                        Node(Color.BLACK, left.right, val, right))

        # Case 2: Left child is Red, Left's Right child is Red
        if left and left.color == Color.RED and left.right and left.right.color == Color.RED:
            return Node(Color.RED,
                        Node(Color.BLACK, left.left, left.val, left.right.left),
                        left.right.val,
                        Node(Color.BLACK, left.right.right, val, right))

        # Case 3: Right child is Red, Right's Left child is Red
        if right and right.color == Color.RED and right.left and right.left.color == Color.RED:
            return Node(Color.RED,
                        Node(Color.BLACK, left, val, right.left.left),
                        right.left.val,
                        Node(Color.BLACK, right.left.right, right.val, right.right))

        # Case 4: Right child is Red, Right's Right child is Red
        if right and right.color == Color.RED and right.right and right.right.color == Color.RED:
            return Node(Color.RED,
                        Node(Color.BLACK, left, val, right.left),
                        right.val,
                        Node(Color.BLACK, right.right.left, right.right.val, right.right.right))

    return Node(color, left, val, right)

def insert(x: int, tree: Optional[Node]) -> Node:
    def ins(n: Optional[Node]) -> Node:
        if n is None:
            return Node(Color.RED, None, x, None)

        if x < n.val:
            return balance(n.color, ins(n.left), n.val, n.right)
        elif x > n.val:
            return balance(n.color, n.left, n.val, ins(n.right))
        else:
            return n

    root = ins(tree)
    root.color = Color.BLACK
    return root

def inorder(tree: Optional[Node]) -> List[int]:
    if tree is None:
        return []
    return inorder(tree.left) + [tree.val] + inorder(tree.right)

def main() -> None:
    values = [7, 3, 18, 10, 22, 8, 11, 26]
    tree: Optional[Node] = None

    for v in values:
        tree = insert(v, tree)

    result = inorder(tree)
    print(result)

if __name__ == "__main__":
    main()

