type Expr = Const(int) | Var(string) | Add(Expr, Expr) | Mul(Expr, Expr)

export func diff(expr: Expr, var: string) -> Expr {
  match expr {
    Const(n) => Const(0),
    Var(v) => if _str_eq(v, var) then Const(1) else Const(0),
    Add(f, g) => Add(diff(f, var), diff(g, var)),
    Mul(f, g) => Add(Mul(f, diff(g, var)), Mul(g, diff(f, var)))
  }
}

export func simplify(expr: Expr) -> Expr {
  match expr {
    Const(n) => Const(n),
    Var(v) => Var(v),
    Add(left, right) => {
      let l = simplify(left);
      let r = simplify(right);
      match l {
        Const(0) => r,
        _ => match r {
          Const(0) => l,
          _ => Add(l, r)
        }
      }
    },
    Mul(left, right) => {
      let l = simplify(left);
      let r = simplify(right);
      match l {
        Const(0) => Const(0),
        Const(1) => r,
        _ => match r {
          Const(0) => Const(0),
          Const(1) => l,
          _ => Mul(l, r)
        }
      }
    }
  }
}

export func exprToString(expr: Expr) -> string {
  match expr {
    Const(n) => "Const(" ++ show(n) ++ ")",
    Var(v) => "Var(" ++ v ++ ")",
    Add(left, right) => "Add(" ++ exprToString(left) ++ ", " ++ exprToString(right) ++ ")",
    Mul(left, right) => "Mul(" ++ exprToString(left) ++ ", " ++ exprToString(right) ++ ")"
  }
}

