from dataclasses import dataclass
from typing import Union

class Expr:
    pass

@dataclass(frozen=True)
class Const(Expr):
    value: int

    def __repr__(self) -> str:
        return f"Const({self.value})"

@dataclass(frozen=True)
class Var(Expr):
    name: str

    def __repr__(self) -> str:
        return f"Var({self.name})"

@dataclass(frozen=True)
class Add(Expr):
    left: Expr
    right: Expr

    def __repr__(self) -> str:
        return f"Add({self.left!r}, {self.right!r})"

@dataclass(frozen=True)
class Mul(Expr):
    left: Expr
    right: Expr

    def __repr__(self) -> str:
        return f"Mul({self.left!r}, {self.right!r})"

def diff(expr: Expr, var: str) -> Expr:
    if isinstance(expr, Const):
        return Const(0)
    if isinstance(expr, Var):
        return Const(1) if expr.name == var else Const(0)
    if isinstance(expr, Add):
        return Add(diff(expr.left, var), diff(expr.right, var))
    if isinstance(expr, Mul):
        # product rule: f * g' + g * f'
        return Add(Mul(expr.left, diff(expr.right, var)), Mul(expr.right, diff(expr.left, var)))
    raise TypeError("Unknown expression type")

def _flatten_add(expr: Expr) -> list[Expr]:
    if isinstance(expr, Add):
        return _flatten_add(expr.left) + _flatten_add(expr.right)
    return [expr]

def _flatten_mul(expr: Expr) -> list[Expr]:
    if isinstance(expr, Mul):
        return _flatten_mul(expr.left) + _flatten_mul(expr.right)
    return [expr]

def simplify(expr: Expr) -> Expr:
    if isinstance(expr, Const) or isinstance(expr, Var):
        return expr

    if isinstance(expr, Add):
        left = simplify(expr.left)
        right = simplify(expr.right)
        terms = []
        for t in _flatten_add(left) + _flatten_add(right):
            terms.append(simplify(t))
        const_sum = sum(t.value for t in terms if isinstance(t, Const))
        non_consts = [t for t in terms if not isinstance(t, Const)]
        if const_sum != 0:
            non_consts.append(Const(const_sum))
        if not non_consts:
            return Const(0)
        result = non_consts[0]
        for t in non_consts[1:]:
            result = Add(result, t)
        return result

    if isinstance(expr, Mul):
        left = simplify(expr.left)
        right = simplify(expr.right)
        factors = []
        for f in _flatten_mul(left) + _flatten_mul(right):
            factors.append(simplify(f))
        # If any factor is 0 -> 0
        if any(isinstance(f, Const) and f.value == 0 for f in factors):
            return Const(0)
        prod = 1
        non_consts = []
        for f in factors:
            if isinstance(f, Const):
                prod *= f.value
            else:
                non_consts.append(f)
        if prod == 0:
            return Const(0)
        if prod != 1:
            non_consts.insert(0, Const(prod))
        if not non_consts:
            return Const(prod)
        result = non_consts[0]
        for f in non_consts[1:]:
            result = Mul(result, f)
        return result

    return expr

def main() -> None:
    # expression: x^2 + 3x + 5
    expr = Add(
        Add(
            Mul(Var("x"), Var("x")),
            Mul(Const(3), Var("x"))
        ),
        Const(5)
    )
    derivative = diff(expr, "x")
    simplified = simplify(derivative)
    print(repr(simplified))

if __name__ == "__main__":
    main()

