from dataclasses import dataclass
from typing import List, Tuple, Union

@dataclass(frozen=True)
class Type:
    """Base class for all types."""
    pass

@dataclass(frozen=True)
class TVar(Type):
    """Represents a type variable."""
    name: str

@dataclass(frozen=True)
class TInt(Type):
    """Represents the integer type."""
    def __repr__(self) -> str:
        return "TInt"

@dataclass(frozen=True)
class TBool(Type):
    """Represents the boolean type."""
    def __repr__(self) -> str:
        return "TBool"

@dataclass(frozen=True)
class TFunc(Type):
    """Represents a function type: arg -> result."""
    arg: Type
    result: Type

# Singleton instances for base types for efficiency and consistent representation
T_INT = TInt()
T_BOOL = TBool()

# Type definition for a substitution: a list of (variable_name, Type) pairs
Substitution = List[Tuple[str, Type]]

class UnificationError(Exception):
    """Custom exception for unification failures."""
    pass

def apply(subst: Substitution, ty: Type) -> Type:
    """
    Applies a substitution to a given type.
    Handles transitive substitutions (e.g., if a -> b and b -> TInt, then a -> TInt).
    """
    if isinstance(ty, TVar):
        for var_name, type_val in subst:
            if ty.name == var_name:
                # Apply the rest of the substitution to the new type
                # to handle cases like [(a, b), (b, TInt)]
                return apply(subst, type_val)
        return ty  # If variable not found in substitution, return itself
    elif isinstance(ty, TFunc):
        return TFunc(apply(subst, ty.arg), apply(subst, ty.result))
    else:  # TInt, TBool
        return ty

def unify(t1: Type, t2: Type) -> Substitution:
    """
    Unifies two types, returning a substitution or raising UnificationError.
    Occurs check is omitted for simplicity as per requirements.
    """
    if t1 == t2:
        return []

    if isinstance(t1, TVar):
        # Unify a type variable with any other type
        return [(t1.name, t2)]
    if isinstance(t2, TVar):
        # Unify any type with a type variable
        return [(t2.name, t1)]

    if isinstance(t1, TFunc) and isinstance(t2, TFunc):
        # Unify function types
        # Unify arguments first
        s1 = unify(t1.arg, t2.arg)

        # Apply the first substitution to the results before unifying them
        applied_r1 = apply(s1, t1.result)
        applied_r2 = apply(s1, t2.result)

        # Unify the (potentially modified) results
        s2 = unify(applied_r1, applied_r2)

        # Combine substitutions. The `apply` function's recursive nature
        # correctly handles the composition of `s1` and `s2` when they are concatenated.
        return s1 + s2

    # If types are not compatible, unification fails
    raise UnificationError(f"Cannot unify {t1} and {t2}")

def main() -> None:
    """
    Main function to demonstrate type unification with the specified example.
    """
    type1_to_unify = TFunc(TVar("a"), T_INT)
    type2_to_unify = TFunc(T_BOOL, TVar("b"))

    try:
        substitution = unify(type1_to_unify, type2_to_unify)
        for var_name, type_val in substitution:
            print(f"{var_name} = {type_val}")
    except UnificationError as e:
        print(f"Unification failed: {e}")

if __name__ == "__main__":
    main()
